<template>
  <layout-make-media
    :main-title="t('textToImage')"
    :example-title="t('aiImageUpscalerExamples')"
  >
    <!-- 左上区域：配置面板 -->
    <template #left-top>
      <ImageUpscalerPanel
        @generate-success="handleGenerateSuccess"
        @generate-error="handleGenerateError"
        @generate-create="handleGenerateCreate"
        @loading="handleLoading"
      />
    </template>

    <!-- 右上区域：结果面板 -->
    <template #right-top>
      <div class="result-panel">
        <media-generate-result 
          :media-type="MEDIA_TYPES.IMAGE" 
          :operation-type="IMAGE_OPERATIONS.ENHANCE"
          :result-state="currentState" 
          :media-data="resultMediaData" 
          :estimatedTime="estimatedTime"
          :error-message="errorMessage"
          @action="handleAction"
          @retry="handleRetry">
        </media-generate-result>
      </div>
    </template>

    <!-- 底部区域：示例展示 -->
    <template #bottom>
      <image-upscaler-examples />
    </template>
  </layout-make-media>
</template>

<script setup>
import { ref, reactive, computed, onMounted } from 'vue';
import { useI18n } from 'vue-i18n';
import { ElMessage } from 'element-plus';
import LayoutMakeMedia from '@/components/layout/media-make.vue';
import ImageUpscalerPanel from './panel/left-panel.vue';
import LImg from '@/components/l-img.vue';
import MediaGenerateResult from '@/components/business/media-generate-result.vue';
import { MEDIA_TYPES, IMAGE_OPERATIONS } from '@/types/media-tool';
import { handleMediaAction } from '@/utils/dialogMethod/media-action-handler.js';
import ImageUpscalerExamples from '@/components/produce-media/upscaler-examples.vue';
import { routerTo } from '@/router/navigation.js';
import { ROUTER_PATHS } from '@/router/constants.js';
import { useMediaGenerationStore } from '@/store/modules/media-generation';
import { downloadImage } from '@/utils/util.js';

const { t } = useI18n();
const mediaStore = useMediaGenerationStore();

// 状态管理 - 只保留UI显示相关的状态
const isGenerating = ref(false);
const estimatedTime = ref(null);
const currentResult = ref(null);
const errorMessage = ref('');
const layoutMakeMedia = ref(null);

// 结果状态管理
const currentState = ref('empty'); // 'empty', 'loading', 'success', 'error'
const resultMediaData = ref({});

const handleGenerateSuccess = (result) => {
  console.log('handleGenerateSuccess:', result);
  currentState.value = 'success';
  resultMediaData.value = result;
};
const handleGenerateError = (error) => {
  console.error('Failed to upscale image:', error);
  currentState.value = 'error';
  errorMessage.value = error.message || t('upscaleFailed');
  ElMessage.error(t('upscaleFailed'));
};
const handleGenerateCreate = (result) => {
  console.log('handleGenerateCreate:', result);
  currentState.value = 'loading';
  isGenerating.value = true;
  resultMediaData.value = result;
  layoutMakeMedia.value?.scrollTo({
    top: 0,
    behavior: 'smooth'
  });
};
const handleLoading = (loading,time) => {
  isGenerating.value = loading;
  estimatedTime.value = time;
  
};

// 处理操作事件
const handleAction = (action) => {
  console.log('handleAction:', action);
  
  // 使用通用的媒体操作处理器
  handleMediaAction(action, resultMediaData.value, {
    onConfirm: (actionType, result) => {
      mediaStore.setGenerationResult(actionType, { imageUrl: result?.data?.url || '' });
      // TODO 临时拦截，后续接口未完成 yangjie
      if (actionType != IMAGE_OPERATIONS.DOWNLOAD) { 
        ElMessage.warning('Unsupported Operation !!!');
        return;
      }
      switch (actionType) {
        case IMAGE_OPERATIONS.DOWNLOAD:
          handleDownloadImage(resultMediaData.value);
          break;
        case IMAGE_OPERATIONS.ENHANCE:
          // 增强图片 - 跳转到图片增强页面
          routerTo(ROUTER_PATHS.IMAGE_ENHANCEMENT, {
            imageUrl: resultMediaData.value.url,
            seed: resultMediaData.value.seed,
            source: 'image-upscaler'
          });
          break;
        case IMAGE_OPERATIONS.EDIT:
          // 编辑图片 - 跳转到图片编辑页面
          routerTo(ROUTER_PATHS.IMAGE_EDITOR, {
            imageUrl: resultMediaData.value.url,
            seed: resultMediaData.value.seed,
            source: 'image-upscaler'
          });
          break;
        case IMAGE_OPERATIONS.TO_VIDEO:
          // 转视频 - 跳转到图片转视频页面
          routerTo(ROUTER_PATHS.IMAGE_TO_VIDEO, {
            imageUrl: resultMediaData.value.url,
            seed: resultMediaData.value.seed,
            source: 'image-upscaler'
          });
          break;
        case IMAGE_OPERATIONS.ENLARGE:
          // 继续放大 - 刷新当前页面数据
          ElMessage.success(t('upscaleCompleted'));
          break;
        default:
          console.warn('Unknown action type:', actionType);
          break;
      }
    },
    onCancel: (actionType, result) => {
      console.log(`${actionType} operation cancelled:`, result);
    }
  });
};

// 处理重试事件
const handleRetry = () => {
  currentState.value = 'empty';
  errorMessage.value = '';
  currentResult.value = null;
  resultMediaData.value = {};
};

// 下载图片功能实现
const handleDownloadImage = async (mediaData) => {
  if (!mediaData?.url) {
    ElMessage.warning(t('noImageToDownload'));
    return;
  }

  try {
    await downloadImage(mediaData.url);
  } catch (error) {
    console.error('Download failed:', error);
  }
};

// 组件挂载时初始化
onMounted(() => {
  layoutMakeMedia.value = document.querySelector('.layout-make-media');
});
</script>

<style lang="scss" scoped>

// 右侧结果面板样式
.result-panel {
  height: 100%;
}
</style>