<template>
  <div class="config-panel">
    <!-- 基础配置区域 -->
    <div class="basic-config">
      <div class="panel-header">
        <div class="panel-title">{{ t('imageEnlargement') }}</div>
        <p class="panel-description">{{ t('selectImageToUpscale') }}</p>
      </div>

      <!-- 图片上传区域 -->
      <div class="form-section">
        <UploadImage
          width="100%"
          height="200px"
          :max-size="4.5"
          :need-compression="true"
          :default-url="formData.uploadedImageUrl"
          @uploadSuccess="handleUploadSuccess"
          @deleteSuccess="handleDeleteSuccess"
        />
      </div>
      
      <!-- 人脸放大开关 -->
      <div class="form-section">
        <div class="upscale-face-section">
          <div class="switch-container">
            <div class="form-label"></div>
            <div class="form-label-value">
              {{ t('upscaleFace') }} 
              <el-switch
                :model-value="formData.upscaleFace"
                @update:model-value="handleUpscaleFaceChange"
                class="upscale-switch"
              />
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- 缩放倍数 -->
    <div class="form-section">
      <div class="label-with-value">
        <label class="form-label">{{ t('scaleImage') }}</label>
        <span class="value-display">{{ formData.scaleMultiplier.toFixed(2) }}x {{ t('upscale') }}</span>
      </div>
      
      <div class="scale-controls">
        <el-slider
          :model-value="formData.scaleMultiplier"
          :min="0.1"
          :max="10"
          :step="0.01"
          class="scale-slider"
          @update:model-value="handleScaleChange"
        />
        <div class="scale-controls-value">
          <div>0.00</div>
          <div>10.00</div>
        </div>
      </div>
    </div>

    <!-- 生成按钮 -->
    <div class="form-actions">
      <el-button
        :loading="isGenerating"
        @click="onGenerateClick"
        :disabled="isButtonDisabled"
        class="generate-button"
        :class="{'disabled': isButtonDisabled}"
        block
      >
        <l-img w="18px" h="18px" src="/static/images/picture-icon.png"></l-img>
        {{ t('generateImage') }}
      </el-button>
    </div>
  </div>
</template>

<script setup>
import { ref, reactive, computed, onMounted, onBeforeUnmount, onUnmounted } from 'vue';
import { useI18n } from 'vue-i18n';
import { ElMessage } from 'element-plus';
import UploadImage from '@/components/upload/image.vue';
import LImg from '@/components/l-img.vue';
import { useMediaGenerationStore } from '@/store/modules/media-generation';
import { addTaskToPolling, TaskType } from '@/presenter/media-task-polling';
import { mediaTaskEventBus, clearMediaTaskEventListeners } from '@/presenter/media-task-events';
import { IMAGE_OPERATIONS } from '@/types/media-tool';
import router from '@/router';

const { t } = useI18n();
const mediaStore = useMediaGenerationStore();
// 当前模块的 key
const MODULE_KEY = IMAGE_OPERATIONS.ENLARGE;

// 内部数据管理
const isGenerating = ref(false);
// 当前任务ID，用于事件过滤
const currentTaskId = ref(null);
const formData = reactive({
  uploadedImage: null,
  uploadedImageUrl: '',
  uploadedImageDimensions: null,
  scaleMultiplier: 2.0,
  upscaleFace: false
});

// Emits定义 - 只发送四个状态事件
const emit = defineEmits(['generate-success', 'generate-error', 'generate-create', 'loading']);

// 获取存储的生成结果
const loadGenerationResult = () => {
  const result = mediaStore.getGenerationResult(MODULE_KEY);
  if (result) {
    // 设置默认图片URL
    if (result.imageUrl) {
      formData.uploadedImageUrl=result.imageUrl;
    }
  }
};


// 清除生成结果
const clearGenerationResult = () => {
  mediaStore.clearGenerationResult(MODULE_KEY);
};

// 计算属性：按钮禁用状态
const isButtonDisabled = computed(() => {
  return !formData.uploadedImage || formData.scaleMultiplier <= 0;
});

// 处理图片上传成功
const handleUploadSuccess = (result) => {
  formData.uploadedImage = result.originalFile;
  formData.uploadedImageUrl = result.url;
  formData.uploadedImageDimensions = result.dimensions;
};

// 处理图片删除成功
const handleDeleteSuccess = () => {
  formData.uploadedImage = null;
  formData.uploadedImageUrl = '';
  formData.uploadedImageDimensions = null;
};

// 处理缩放倍数变化
const handleScaleChange = (value) => {
  formData.scaleMultiplier = value;
};

// 处理人脸放大开关变化
const handleUpscaleFaceChange = (value) => {
  formData.upscaleFace = value;
};

// 处理任务完成事件
const handleTaskCompleted = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    // 计算新的尺寸
    const originalDimensions = formData.uploadedImageDimensions || { width: 512, height: 512 };
    const newDimensions = {
      width: Math.round(originalDimensions.width * formData.scaleMultiplier),
      height: Math.round(originalDimensions.height * formData.scaleMultiplier)
    };
    
    // 构造结果数据
    const result = {
      id: Date.now(),
      imageUrl: res.result?.media_list?.[0]?.file_url || `https://picsum.photos/${newDimensions.width}/${newDimensions.height}?random=${Date.now()}`,
      scaleMultiplier: formData.scaleMultiplier.toFixed(2),
      upscaleFace: formData.upscaleFace,
      originalDimensions,
      newDimensions,
      createdAt: new Date().toISOString()
    };
    
    emit('generate-success', result);
    isGenerating.value = false;
    currentTaskId.value = null;
  }
};

// 处理任务失败事件
const handleTaskFailed = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    emit('generate-error', res);
    isGenerating.value = false;
    currentTaskId.value = null;
  }
};

// 处理任务状态更新事件
const handleTaskStatusUpdate = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    // 更新进度等信息
    console.log(`Image upscaling progress: ${res.res.progress}%`);
    emit('loading', true, res.res.estimated_time || null);
  }
};

// 业务逻辑区域


// 处理生成按钮点击
const onGenerateClick = async () => {
  try {
    // 发送开始生成事件
    emit('generate-create');
    emit('loading', true, null);
    isGenerating.value = true;
    
    // 准备请求数据
    const requestData = {
      uploadedImage: formData.uploadedImage,
      uploadedImageUrl: formData.uploadedImageUrl,
      uploadedImageDimensions: formData.uploadedImageDimensions,
      scaleMultiplier: formData.scaleMultiplier,
      upscaleFace: formData.upscaleFace
    };

    console.log('Image upscaling with data:', requestData);
    
    // TODO: 调用真实的API (暂时忽略，接口不支持)
    // const result = await apiGeneration.imageUpscale(requestData);
    
    // 模拟API响应
    const apiResult = {
      task_id: `task_upscale_${Date.now()}`,
      status: 'pending'
    };
    
    // 设置路由meta并添加到轮询管理器
    const meta = router.currentRoute.value.meta;
    meta.taskId = apiResult.task_id;
    meta.type = TaskType.IMAGE; // 使用现有的类型
    addTaskToPolling(apiResult.task_id, TaskType.IMAGE);
    
    // 设置当前任务ID
    currentTaskId.value = apiResult.task_id;
    
  } catch (error) {
    emit('loading', false, null);
    isGenerating.value = false;
    emit('generate-error', error);
  }
};

// 生命周期钩子
onMounted(() => {
  // 获取之前保存的生成结果
  loadGenerationResult();
  
  // 绑定媒体任务事件监听器（只绑定一次）
  mediaTaskEventBus.on('task-completed', handleTaskCompleted);
  mediaTaskEventBus.on('task-failed', handleTaskFailed);
  mediaTaskEventBus.on('task-status-update', handleTaskStatusUpdate);
});

// 组件卸载前清理生成结果
onBeforeUnmount(() => {
  clearGenerationResult();
  // 清理事件监听器（只清理一次）
  clearMediaTaskEventListeners();
});
</script>

